function describeEmpty(p) {
  if (!p) return { score: 0, feedback: ["Password is required"] };
  return { score: 0, feedback: [] };
}

function lengthFeedback(p) {
  return p.length >= 8 ? [] : ["Add more characters (min 8)"];
}

function failedMessages(results, messages) {
  return messages.filter((m, i) => !results[i]);
}

function describePasswordStrength(password) {
  if (!password) {
    return { score: 0, feedback: ["Password is required"] };
  }
  const rules = [
    { check: (p) => p.length >= 8, message: "Add more characters (min 8)" },
    { check: (p) => /[A-Z]/.test(p), message: "Add an uppercase letter" },
    { check: (p) => /[0-9]/.test(p), message: "Add a number" },
  ];
  let score = 0;
  const feedback = [];
  for (const rule of rules) {
    if (rule.check(password)) score++;
    else feedback.push(rule.message);
  }
  return { score, feedback };
}

function describePasswordStrength(password) {
  if (!password) {
    return { score: 0, feedback: ["Password is required"] };
  }
  const rules = [
    { check: (p) => p.length >= 10, message: "Use at least 10 characters" },
    { check: (p) => /[a-z]/.test(p), message: "Add a lowercase letter" },
    { check: (p) => /[0-9]/.test(p), message: "Add a number" },
  ];
  let score = 0;
  const feedback = [];
  for (const rule of rules) {
    if (rule.check(password)) score++;
    else feedback.push(rule.message);
  }
  return { score, feedback };
}

function describePasswordStrength(password, common) {
  if (common.includes(password)) {
    return { score: 0, feedback: ["This password is too common"] };
  }
  if (!password) {
    return { score: 0, feedback: ["Password is required"] };
  }
  let score = 0;
  const feedback = [];
  if (password.length >= 8) score++;
  else feedback.push("Add more characters (min 8)");
  if (/[0-9]/.test(password)) score++;
  else feedback.push("Add a number");
  return { score, feedback };
}

function runRules(password, rules) {
  let score = 0;
  const feedback = [];
  for (const rule of rules) {
    if (rule.check(password)) score++;
    else feedback.push(rule.message);
  }
  return { score, feedback };
}
